// Set as the errorWorkflow on the other workflows, so a failure anywhere
// lands here instead of disappearing into an execution list nobody reads.
//
// Deliberately does not retry: these workflows are notification glue, and a
// failed notification must never be mistaken for a failed ticket. The ticket
// is safe in Postgres either way - the worker records notified=false and the
// ticket stays AWAITING_APPROVAL regardless of whether n8n ever heard about
// it.
const e = $input.first().json;

return [{
  json: {
    failed_workflow: e.workflow?.name ?? 'unknown',
    failed_node: e.execution?.lastNodeExecuted ?? 'unknown',
    message: e.execution?.error?.message ?? 'no message',
    execution_url: e.execution?.url ?? null,
    at: new Date().toISOString(),
    // Where a real deployment would send this: Slack, PagerDuty, email.
    // Left as structured output so the routing is a one-node change.
    severity: e.workflow?.name === 'Ticket approval' ? 'high' : 'low',
  },
}];
